// Jenkinsfile — 4-Stage Test Pipeline
// Generated by bestest ci jenkins
//
// 4-stage architecture:
//   1. Fast      — Unit tests (<5min), coverage gate
//   2. Medium    — Integration tests (<20min), retry(3)
//   3. Slow      — E2E / Playwright tests (<60min), retry(3)
//   4. Quality   — Mutation testing / nightly (cron trigger only)
//
// Multi-language monorepo: parallel branches per detected language within each stage.
// Coverage gate reads coverage.target from .bestest/config.yaml (default: 80%).
//
// Prerequisites:
//   - .bestest/config.yaml with ci.enabled=true, ci.provider=jenkins
//   - StackProfile at .bestest/state/stack-profile.json for language detection
//   - Jenkins agents with: Node.js 20+, Python 3.12+, JDK 17+, Go 1.22+
//   - Required plugins: pipeline, workflow-aggregator, credentials-binding

pipeline {
    agent none

    environment {
        COVERAGE_THRESHOLD = '80'
        NODE_VERSION       = '20'
        PYTHON_VERSION     = '3.12'
        JAVA_VERSION       = '17'
        GO_VERSION         = '1.22'
    }

    options {
        timeout(time: 2, unit: 'HOURS')
        buildDiscarder(logRotator(numToKeepStr: '30'))
        ansiColor('xterm')
    }

    triggers {
        // Nightly build for Stage 4 (Quality)
        cron('0 2 * * *')
    }

    stages {
        // ====================================================================
        // Stage 1: Fast — Unit Tests (parallel per language)
        // ====================================================================
        stage('Fast') {
            parallel {
                stage('Fast – JS/TS') {
                    agent { label 'node' }
                    steps {
                        checkout scm
                        sh 'npm ci'
                        sh '''
                            npx vitest run --reporter=verbose src/**/*.test.{ts,tsx} --coverage

                            COVERAGE=$(cat coverage/coverage-summary.json | jq '.total.lines.pct')
                            echo "JS/TS Coverage: ${COVERAGE}%"

                            if [ "$(echo "$COVERAGE < $COVERAGE_THRESHOLD" | bc -l)" -eq 1 ]; then
                                echo "ERROR: Coverage ${COVERAGE}% is below threshold ${COVERAGE_THRESHOLD}%"
                                exit 1
                            fi
                        '''
                    }
                    post {
                        always {
                            archiveArtifacts artifacts: 'coverage/**', allowEmptyArchive: true
                        }
                    }
                }

                stage('Fast – Python') {
                    agent { label 'python' }
                    steps {
                        checkout scm
                        sh 'pip install -r requirements.txt pytest pytest-cov 2>/dev/null || pip install pytest pytest-cov'
                        sh '''
                            pytest tests/unit/ -m unit -v --tb=short --cov --cov-report=json:coverage.json

                            COVERAGE=$(python -c "import json; print(json.load(open('coverage.json'))['totals']['percent_covered'])")
                            echo "Python Coverage: ${COVERAGE}%"

                            if [ "$(echo "$COVERAGE < $COVERAGE_THRESHOLD" | bc -l)" -eq 1 ]; then
                                echo "ERROR: Coverage ${COVERAGE}% is below threshold ${COVERAGE_THRESHOLD}%"
                                exit 1
                            fi
                        '''
                    }
                    post {
                        always {
                            archiveArtifacts artifacts: 'coverage.json', allowEmptyArchive: true
                        }
                    }
                }

                stage('Fast – Java') {
                    agent { label 'java' }
                    steps {
                        checkout scm
                        sh '''
                            if [ -f "gradlew" ]; then
                                ./gradlew test --no-daemon jacocoTestReport
                            elif [ -f "mvnw" ]; then
                                ./mvnw test jacoco:report
                            fi
                        '''
                    }
                    post {
                        always {
                            archiveArtifacts artifacts: 'build/reports/jacoco/**', allowEmptyArchive: true
                            junit 'build/test-results/**/*.xml'
                        }
                    }
                }

                stage('Fast – Go') {
                    agent { label 'go' }
                    steps {
                        checkout scm
                        sh '''
                            go test -short -v -coverprofile=coverage.out -covermode=atomic ./...

                            COVERAGE=$(go tool cover -func=coverage.out | grep total | awk '{print $3}' | tr -d '%')
                            echo "Go Coverage: ${COVERAGE}%"

                            if [ "$(echo "$COVERAGE < $COVERAGE_THRESHOLD" | bc -l)" -eq 1 ]; then
                                echo "ERROR: Coverage ${COVERAGE}% is below threshold ${COVERAGE_THRESHOLD}%"
                                exit 1
                            fi
                        '''
                    }
                    post {
                        always {
                            archiveArtifacts artifacts: 'coverage.out', allowEmptyArchive: true
                        }
                    }
                }
            }
        }

        // ====================================================================
        // Stage 2: Medium — Integration Tests (parallel per language, retry)
        // ====================================================================
        stage('Medium') {
            parallel {
                stage('Medium – JS/TS') {
                    agent { label 'node' }
                    steps {
                        checkout scm
                        sh 'npm ci'
                        retry(3) {
                            sh 'npx vitest run --reporter=verbose "tests/integration/**"'
                        }
                    }
                }

                stage('Medium – Python') {
                    agent { label 'python' }
                    steps {
                        checkout scm
                        sh 'pip install -r requirements.txt pytest 2>/dev/null || pip install pytest'
                        retry(3) {
                            sh 'pytest tests/integration/ -m integration -v --tb=short'
                        }
                    }
                }

                stage('Medium – Java') {
                    agent { label 'java' }
                    steps {
                        checkout scm
                        retry(3) {
                            sh '''
                                if [ -f "gradlew" ]; then
                                    ./gradlew integrationTest --no-daemon
                                elif [ -f "mvnw" ]; then
                                    ./mvnw verify -Dgroups="integration"
                                fi
                            '''
                        }
                    }
                }

                stage('Medium – Go') {
                    agent { label 'go' }
                    steps {
                        checkout scm
                        retry(3) {
                            sh 'go test -v -tags=integration ./integration/... ./itest/...'
                        }
                    }
                }
            }
        }

        // ====================================================================
        // Stage 3: Slow — E2E Tests (parallel per language, retry)
        // ====================================================================
        stage('Slow') {
            parallel {
                stage('Slow – JS/TS E2E') {
                    agent { label 'node' }
                    steps {
                        checkout scm
                        sh 'npm ci'
                        sh 'npx playwright install --with-deps'
                        retry(3) {
                            sh 'npx playwright test'
                        }
                    }
                    post {
                        always {
                            archiveArtifacts artifacts: 'playwright-report/**', allowEmptyArchive: true
                        }
                    }
                }

                stage('Slow – Python E2E') {
                    agent { label 'python' }
                    steps {
                        checkout scm
                        sh 'pip install -r requirements.txt pytest playwright 2>/dev/null || pip install pytest playwright'
                        sh 'playwright install --with-deps'
                        retry(3) {
                            sh 'pytest tests/e2e/ -m e2e -v --tb=short'
                        }
                    }
                }

                stage('Slow – Java E2E') {
                    agent { label 'java' }
                    steps {
                        checkout scm
                        retry(3) {
                            sh '''
                                if [ -f "gradlew" ]; then
                                    ./gradlew e2eTest --no-daemon
                                elif [ -f "mvnw" ]; then
                                    ./mvnw verify -Dgroups="e2e"
                                fi
                            '''
                        }
                    }
                }
            }
        }

        // ====================================================================
        // Stage 4: Quality — Mutation Testing (Nightly/Manual only)
        // ====================================================================
        stage('Quality') {
            when {
                anyOf {
                    triggeredBy 'TimerTrigger'
                    triggeredBy cause: "UserIdCause"
                }
            }
            agent { label 'node' }
            steps {
                checkout scm
                sh 'npm ci'
                sh '''
                    npx stryker run

                    SCORE=$(jq '.mutationScore' reports/mutation/json)
                    echo "Mutation Score: ${SCORE}%"

                    if [ "$(echo "$SCORE < 80" | bc -l)" -eq 1 ]; then
                        echo "ERROR: Mutation score ${SCORE}% is below threshold 80%"
                        exit 1
                    fi
                '''
            }
        }
    }

    post {
        always {
            echo "Pipeline completed: ${currentBuild.currentResult}"
        }
        failure {
            echo "Pipeline FAILED — check stage logs for details"
        }
        success {
            echo "All stages PASSED — test pipeline green"
        }
    }
}
